    "code": "#include \"ch32fun.h\"\n#include <stdio.h>\n\n// Functions with __attribute__((constructor)) will be run by SystemInit()\n// and increment this counter\nstatic unsigned ctor_count = 0;\n\n__attribute__((constructor)) static void ctor_fn1(void)\n{\n\tctor_count++;\n}\n\n__attribute__((constructor)) static void ctor_fn2(void)\n{\n\tctor_count++;\n}\n\nint main()\n{\n\tSystemInit();\n\n\tprintf(\"Constructors called: %u\\n\", ctor_count);\n\n\twhile (1) {\n\t\t__WFE(); // Sleep\n\t}\n}\n",
    "funconfig": "#ifndef _FUNCONFIG_H\n#define _FUNCONFIG_H\n\n// Run constructors on SystemInit(). Alternatively you can remove this and\n// invoke CallConstructors() yourself whenever you want.\n#define FUNCONF_SUPPORT_CONSTRUCTORS 1\n\n// For debugging\n#define FUNCONF_USE_DEBUGPRINTF 1\n\n#endif\n\n"
