    "code": "#include \"ch32fun.h\"\n#include <stdio.h>\n\nuint32_t count;\n\nint main()\n{\n\tSystemInit();\n\n\t// Enable GPIOs\n\tRCC->APB2PCENR |= RCC_APB2Periph_GPIOD | RCC_APB2Periph_GPIOC;\n\n\t// GPIO D0 Push-Pull\n\tGPIOD->CFGLR &= ~(0xf<<(4*0));\n\tGPIOD->CFGLR |= (GPIO_Speed_10MHz | GPIO_CNF_OUT_PP)<<(4*0);\n\n\t// GPIO D4 Push-Pull\n\tGPIOD->CFGLR &= ~(0xf<<(4*4));\n\tGPIOD->CFGLR |= (GPIO_Speed_10MHz | GPIO_CNF_OUT_PP)<<(4*4);\n\n\t// GPIO C0 Push-Pull\n\tGPIOC->CFGLR &= ~(0xf<<(4*0));\n\tGPIOC->CFGLR |= (GPIO_Speed_10MHz | GPIO_CNF_OUT_PP)<<(4*0);\n\n\twhile(1)\n\t{\n\t\tGPIOD->BSHR = 1 | (1<<4);\t // Turn on GPIOs\n\t\tGPIOC->BSHR = 1;\n\t\tDelay_Ms( 250 );\n\t\tGPIOD->BSHR = (1<<16) | (1<<(16+4)); // Turn off GPIODs\n\t\tGPIOC->BSHR = (1<<16);\n\t\tDelay_Ms( 250 );\n\t\tcount++;\n\t}\n}\n",
    "funconfig": "#ifndef _FUNCONFIG_H\n#define _FUNCONFIG_H\n\n// Place configuration items here, you can see a full list in ch32fun/ch32fun.h\n// To reconfigure to a different processor, update TARGET_MCU in the  Makefile\n\n#define FUNCONF_USE_HSE 1               // Use External Oscillator\n#define FUNCONF_USE_PLL 0               // Do not use built-in 2x PLL \n\n#endif\n\n"
