    "id": "spi_24L01_rx.c",
    "name": "spi_24L01_rx.c",
    "title": "nRF24L01 2.4 GHz RF Receiver",
    "category": "SPI & Radios",
    "description": "Packet reception with Nordic nRF24L01+ wireless transceivers.",
