    "code": "#include \"ch32fun.h\"\n#include <stdio.h>\n\nint main()\n{\n\tSystemInit();\n\n\t// Enable timers\n\tRCC->APB2PCENR |= RCC_APB2Periph_TIM1;\n\tRCC->APB1PCENR |= RCC_APB1Periph_TIM2;\n\n\t// Reset TIM1 to init all regs\n\tRCC->APB2PRSTR |= RCC_APB2Periph_TIM1;\n\tRCC->APB2PRSTR &= ~RCC_APB2Periph_TIM1;\n\t\n\t// Reset TIM2 to init all regs\n\tRCC->APB1PRSTR |= RCC_APB1Periph_TIM2;\n\tRCC->APB1PRSTR &= ~RCC_APB1Periph_TIM2;\n\n\t// Prescaler 1 tick = 1 ms\n\tTIM1->PSC = FUNCONF_SYSTEM_CORE_CLOCK / 1000 - 1;\n\t\n\t// Reload period 1000 ticks = 1s\n\tTIM1->ATRLR = 1000 - 1;\n\n\t// Reload immediately\n\tTIM1->SWEVGR |= TIM_UG;\n\n\t// Set TIM1 as a master with TRGO configured to trigger on an update event\n\tTIM1->CTLR2 |= TIM_TRGOSource_Update;\n\t\n\t// Select TRIGO of TIM1 as CLK source for TIM2\n\tTIM2->SMCFGR |= TIM_TS_ITR0\n\t\t\t\t |  TIM_SlaveMode_External1\n\t\t\t\t |  TIM_SlaveMode_Trigger;\n\t\n\t// Prescaler so each tick of this timer is equal\n\t// to TIM1->PSC * TIM1->ATRLR * TIM2->PSC \"SystemTicks\"\n\t//TIM2->PSC = 10 - 1;\n\t\n\t// TIM2 refresh period\n\tTIM2->ATRLR = 0xFFFF;\n\n\t// Enable Timers\n\tTIM1->CTLR1 |= TIM_CEN;\n\tTIM2->CTLR1 |= TIM_CEN;\n\n\twhile(1)\n\t{\n\t\tuint16_t ms = TIM1->CNT;\n\t\tuint16_t s = TIM2->CNT;\n\t\tprintf(\"%d.%03d s\\r\\n\", s, ms);\n\t\tDelay_Ms(500);\n\t}\n}\n\n",
    "funconfig": "#ifndef _FUNCONFIG_H\n#define _FUNCONFIG_H\n\n// Place configuration items here, you can see a full list in ch32fun/ch32fun.h\n// To reconfigure to a different processor, update TARGET_MCU in the  Makefile\n\n#endif\n\n"
