    "id": "rv003usb_gamepad.c",
    "name": "rv003usb_gamepad.c",
    "title": "rv003usb: Software USB HID Gamepad",
    "category": "Software USB (rv003usb)",
    "description": "Official Charles Lohr bit-banged USB 1.1 HID Gamepad for CH32V003.",
    "mcus": [
      "ch32v003",
      "ch32v006"
    ],
    "code": "#include \"ch32fun.h\"\n#include <stdio.h>\n#include <string.h>\n#include \"rv003usb.h\"\n\nint main()\n{\n\tSystemInit();\n\tDelay_Ms(1); // Ensures USB re-enumeration after bootloader or reset; Spec demand >2.5µs ( TDDIS )\n\tusb_setup();\n\twhile(1);\n}\n\nvoid usb_handle_user_in_request( struct usb_endpoint * e, uint8_t * scratchpad, int endp, uint32_t sendtok, struct rv003usb_internal * ist )\n{\n\tif( endp )\n\t{\n\t\tstatic uint8_t tsajoystick[8] = { 0x00, 0x01, 0x10, 0x00 };\n\t\ttsajoystick[0]++;  // Go left->right fast\n\t\ttsajoystick[2] = tsajoystick[0] & 0x80; // Alter button 1.\n\t\tusb_send_data( tsajoystick, 3, 0, sendtok );\n\t}\n\telse\n\t{\n\t\t// If it's a control transfer, nak it.\n\t\tusb_send_empty( sendtok );\n\t}\n}\n\n\n",
    "funconfig": "#ifndef _FUNCONFIG_H\n#define _FUNCONFIG_H\n\n#define FUNCONF_USE_DEBUGPRINTF  1\n#define FUNCONF_SYSTICK_USE_HCLK 1\n\n#endif\n\n",
    "extraFiles": {
      "usb_config.h": "#ifndef _USB_CONFIG_H\n#define _USB_CONFIG_H\n\n#include \"funconfig.h\"\n\n//Defines the number of endpoints for this device. (Always add one for EP0). For two EPs, this should be 3.\n#define ENDPOINTS 2\n\n#define USB_PORT D     // [A,C,D] GPIO Port to use with D+, D- and DPU\n#define USB_PIN_DP 3   // [0-4] GPIO Number for USB D+ Pin\n#define USB_PIN_DM 4   // [0-4] GPIO Number for USB D- Pin\n#define USB_PIN_DPU 5  // [0-7] GPIO for feeding the 1.5k Pull-Up on USB D- Pin; Comment out if not used / tied to 3V3!\n\n#define RV003USB_OPTIMIZE_FLASH    1 // Only disable it if you need to save 16 bytes of RAM or you want to customize usb_pid_handle_ack or usb_pid_handle_setup\n#define RV003USB_OPTIMIZE_FLASH    0\n#define RV003USB_HANDLE_IN_REQUEST 1\n#define RV003USB_OTHER_CONTROL     0\n#define RV003USB_HANDLE_USER_DATA  0\n#define RV003USB_HID_FEATURES      0\n\n#ifndef __ASSEMBLER__\n\n#include <tinyusb_hid.h>\n#include <tusb_types.h>\n\n#ifdef INSTANCE_DESCRIPTORS\n\n//Taken from http://www.usbmadesimple.co.uk/ums_ms_desc_dev.htm\nstatic const uint8_t device_descriptor[] = {\n\t18, //Length\n\tTUSB_DESC_DEVICE,  //Type (Device)\n\t0x10, 0x01, //Spec\n\tTUSB_CLASS_HID, //Device Class\n\t0x0, //Device Subclass\n\t0x0, //Device Protocol  (000 = use config descriptor)\n\t0x08, //Max packet size for EP0 (This has to be 8 because of the USB Low-Speed Standard)\n\t0x09, 0x12, //ID Vendor\n\t0x03, 0xc0, //ID Product\n\t0x02, 0x00, //ID Rev\n\t1, //Manufacturer string\n\t2, //Product string\n\t3, //Serial string\n\t1, //Max number of configurations\n};\n\nstatic const uint8_t gamepad_hid_desc[] = {  //From http://eleccelerator.com/tutorial-about-usb-hid-report-descriptors/\nHID_USAGE_PAGE ( HID_USAGE_PAGE_DESKTOP     ),\nHID_USAGE      ( HID_USAGE_DESKTOP_GAMEPAD  ),\nHID_COLLECTION ( HID_COLLECTION_PHYSICAL ),\n\t//HID_REPORT_ID( 1 )\n\tHID_USAGE_PAGE   ( HID_USAGE_PAGE_DESKTOP                 ),\n\tHID_LOGICAL_MIN  ( 0x81                                   ),\n\tHID_LOGICAL_MAX  ( 0x7f                                   ),\n\tHID_USAGE        ( HID_USAGE_DESKTOP_X                    ),\n\tHID_USAGE        ( HID_USAGE_DESKTOP_Y                    ),\n\tHID_REPORT_COUNT ( 2                                      ),\n\tHID_REPORT_SIZE  ( 8                                      ),\n\tHID_INPUT        ( HID_DATA | HID_VARIABLE | HID_ABSOLUTE ),\n\tHID_USAGE_PAGE   ( HID_USAGE_PAGE_BUTTON                  ),\n\tHID_USAGE_MIN    ( 1                                      ),\n\tHID_USAGE_MAX    ( 8                                      ),\n\tHID_LOGICAL_MIN  ( 0                                      ),\n\tHID_LOGICAL_MAX  ( 1                                      ),\n\tHID_REPORT_COUNT ( 8                                      ),\n\tHID_REPORT_SIZE  ( 1                                      ),\n\tHID_INPUT        ( HID_DATA | HID_VARIABLE | HID_ABSOLUTE ),\nHID_COLLECTION_END\n};\n\nstatic const uint8_t config_descriptor[] = {\n\t// configuration descriptor, USB spec 9.6.3, page 264-266, Table 9-10\n\t9,                        // bLength;\n\tTUSB_DESC_CONFIGURATION,  // bDescriptorType;\n\t0x22, 0x00,               // wTotalLength\n\t0x01,                     // bNumInterfaces (Normally 1)\n\t0x01,                     // bConfigurationValue\n\t0x00,                     // iConfiguration\n\t0x80,                     // bmAttributes (was 0xa0)\n\t0x64,                     // bMaxPower (200mA)\n\n\t//Joystick  (It is unusual that this would be here)\n\t9,                        // bLength\n\tTUSB_DESC_INTERFACE,      // bDescriptorType\n\t0,                        // bInterfaceNumber  = 1 instead of 0 -- well make it second.\n\t0,                        // bAlternateSetting\n\t1,                        // bNumEndpoints\n\tTUSB_CLASS_HID,           // bInterfaceClass (0x03 = HID)\n\tHID_SUBCLASS_NONE,        // bInterfaceSubClass\n\tHID_PROTOCOL_NONE,        // bInterfaceProtocol (1 = Keyboard, 2 = Mouse)\n\t0,                        // iInterface\n\n\t9,                        // bLength\n\tHID_DESC_TYPE_HID,        // bDescriptorType (HID)\n\t0x10,0x01,                // bcd 1.10\n\t0x00,                     //country code\n\t0x01,                     // Num descriptors\n\tHID_DESC_TYPE_REPORT,     // DescriptorType[0] (HID)\n\tsizeof(gamepad_hid_desc), 0x00,     // Descriptor length XXX This looks wrong!!!\n\n\t7,                        // endpoint descriptor (For endpoint 1)\n\tTUSB_DESC_ENDPOINT,       // Endpoint Descriptor (Must be 5)\n\t0x81,                     // Endpoint Address\n\t0x03,                     // Attributes\n\t0x03, 0x00,               // Size\n\t1,                        // Interval (Was 0x0a)\n};\n\n\n\n// keyboard example at:\n//From http://codeandlife.com/2012/06/18/usb-hid-keyboard-with-v-usb/\n\n\n//Ever wonder how you have more than 6 keys down at the same time on a USB keyboard?  It's easy. Enumerate two keyboards!\n\n#define STR_MANUFACTURER u\"CNLohr\"\n#define STR_PRODUCT      u\"RV003USB Demo Gamepad\"\n#ifndef STR_SERIAL\n#define STR_SERIAL       u\"000\"\n#endif\n\nstruct usb_string_descriptor_struct {\n\tuint8_t bLength;\n\tuint8_t bDescriptorType;\n\tuint16_t wString[];\n};\nconst static struct usb_string_descriptor_struct string0 __attribute__((section(\".rodata\"))) = {\n\t4,\n\t3,\n\t{0x0409}\n};\nconst static struct usb_string_descriptor_struct string1 __attribute__((section(\".rodata\")))  = {\n\tsizeof(STR_MANUFACTURER),\n\t3,\n\tSTR_MANUFACTURER\n};\nconst static struct usb_string_descriptor_struct string2 __attribute__((section(\".rodata\")))  = {\n\tsizeof(STR_PRODUCT),\n\t3,\n\tSTR_PRODUCT\n};\nconst static struct usb_string_descriptor_struct string3 __attribute__((section(\".rodata\")))  = {\n\tsizeof(STR_SERIAL),\n\t3,\n\tSTR_SERIAL\n};\n\n// This table defines which descriptor data is sent for each specific\n// request from the host (in wValue and wIndex).\nconst static struct descriptor_list_struct {\n\tuint32_t\tlIndexValue;\n\tconst uint8_t\t*addr;\n\tuint8_t\t\tlength;\n} descriptor_list[] = {\n\t{0x00000100, device_descriptor, sizeof(device_descriptor)},\n\t{0x00000200, config_descriptor, sizeof(config_descriptor)},\n\t// interface number // 2200 for hid descriptors.\n\t{0x00002200, gamepad_hid_desc, sizeof(gamepad_hid_desc)},\n\t{0x00002100, config_descriptor + 18, 9 }, // Not sure why, this seems to be useful for Windows + Android.\n\n\t{0x00000300, (const uint8_t *)&string0, 4},\n\t{0x04090301, (const uint8_t *)&string1, sizeof(STR_MANUFACTURER)},\n\t{0x04090302, (const uint8_t *)&string2, sizeof(STR_PRODUCT)},\t\n\t{0x04090303, (const uint8_t *)&string3, sizeof(STR_SERIAL)}\n};\n#define DESCRIPTOR_LIST_ENTRIES ((sizeof(descriptor_list))/(sizeof(struct descriptor_list_struct)) )\n\n#endif // INSTANCE_DESCRIPTORS\n\n#endif\n\n#endif \n"
    }
